// PesoPlus-Back category flyer, preserving the supplied artwork and QR footer.
let pesoBackImage=null,pesoBackBackground=null;
const pesoBackGroups=[
 {name:'Kitchen & Dining',x:20,y:495,w:1240,h:291,photo:190,edges:[20,227,418,640,836,1051,1260],items:[['Plate 4.5”',15],['Tall Acrylic Tumbler 360ml',29],['K Bowl 7”',29],["Spoon 6’s",89],['Glass Tumbler',19],['Greenish Fruit Plate 9”',45]]},
 {name:'Home Organizers',x:20,y:855,w:608,h:259,photo:169,edges:[20,207,422,628],items:[['Lunch Box',25],['Basin Color',99],['Food Keeper',69]]},
 {name:'Home Textiles',x:647,y:855,w:613,h:259,photo:166,edges:[647,840,1064,1260],items:[['Doormat 40×60',159],['Ground Mat 200×180',279],['Asst. Bath Towel 140×70',85]]},
 {name:'Household Cleaning',x:20,y:1184,w:617,h:269,photo:174,edges:[20,174,333,486,637],items:[['Net Scrub 25g',19],['Hanger w/ Clips',22],['Pail Black 2.5gal',39],['Pail Color 4gal',49]]},
 {name:'Personal Care',x:654,y:1184,w:606,h:269,photo:174,edges:[654,797,955,1090,1260],items:[['Max Blade',19],['122 Nail Polish',29],['Nail Cutter',29],["Beybiko Pocket Wipes Floral 20’s",20]]},
 {name:'Hardware & Tools',x:20,y:1521,w:675,h:242,photo:155,edges:[20,207,367,544,695],items:[['T Torch Original Lighter',15],['Shelf Bracket 6×8',20],['Rope 12mm',19],['Cata LED Bulb 18W',79]]},
 {name:'Toys & Party',x:711,y:1521,w:549,h:242,photo:155,edges:[711,893,1081,1260],items:[['Snake',39],['Squishy Bun',39],['Rubber Ball 60g',29]]}
];
function pesoBackState(){if(!state.pesoBack)state.pesoBack={designVersion:1,slots:pesoBackGroups.flatMap((g,group)=>g.items.map((_,i)=>({productId:`peso-back1-${group}-${i}`,group,discountPercent:0,image:null})))};if(!state.pesoBack.groupNames)state.pesoBack.groupNames=pesoBackGroups.map(g=>g.name);return state.pesoBack}
pesoBackGroups.forEach((g,i)=>$('pesoBackLabel-'+i).addEventListener('input',e=>{pesoBackState().groupNames[i]=e.target.value.trim()||g.name;renderPoster();save()}));
const PESO_BACK_RIBBONS=[[19,443,1238,46],[19,805,609,44],[646,805,612,44],[19,1136,616,43],[654,1136,604,43],[19,1473,675,42],[711,1473,548,42]];
function pesoBackCard(index){const slot=pesoBackState().slots[index],g=pesoBackGroups[slot.group],siblings=pesoBackState().slots.filter(s=>s.group===slot.group),i=siblings.indexOf(slot);return {...g,x:siblings.length===g.items.length?g.edges[i]:g.x+i*g.w/siblings.length,w:siblings.length===g.items.length?g.edges[i+1]-g.edges[i]:g.w/siblings.length}}

async function initPesoBack(){try{
 pesoBackImage=await loadCanvasImage(PESO_BACK_ART);pesoBackBackground=productFreeArtwork(pesoBackImage,1280,1924,[...pesoBackGroups.map(g=>[g.x,g.y,g.w,g.h]),[543,1515,145,10]]);
 const sx=pesoBackImage.naturalWidth/1280,sy=pesoBackImage.naturalHeight/1924;
 pesoBackGroups.forEach((g,group)=>g.items.forEach(([name,price],i)=>{const id=`peso-back1-${group}-${i}`;if(state.products.some(p=>p.id===id)||state.deletedProductIds?.includes(id))return;const x=g.edges[i]+3,w=g.edges[i+1]-g.edges[i]-6,c=document.createElement('canvas');c.width=Math.round(w*sx);c.height=Math.round(g.photo*sy);const ctx=c.getContext('2d');ctx.imageSmoothingQuality='high';ctx.drawImage(pesoBackImage,x*sx,g.y*sy,w*sx,g.photo*sy,0,0,c.width,c.height);state.products.push({id,templateId:'peso-back',name,price,code:`PESO-BACK-${group+1}-${i+1}`,image:c.toDataURL('image/png')})}));pesoBackState();renderAll();save();
 }catch(error){console.error(error);showNotice('Could not load PesoPlus-Back. Reload to try again.')}}
async function pesoBackCanvas({width=1650,height=2550}={}){
 await document.fonts.load('800 20px Outfit');if(!pesoBackBackground)throw Error('Home Express artwork is loading');const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d');ctx.imageSmoothingQuality='high';ctx.scale(width/1280,height/1924);ctx.drawImage(pesoBackBackground,0,0,1280,1924);
 pesoBackGroups.forEach((g,i)=>{const [rx,ry,rw,rh]=PESO_BACK_RIBBONS[i],label=(pesoBackState().groupNames[i]||g.name).toUpperCase();ctx.save();ctx.fillStyle='#ffdc02';ctx.fillRect(rx,ry,rw,rh);ctx.fillStyle='#000';ctx.textAlign='left';everydayText(ctx,label,rx+10,ry+rh*0.72,rw-20,rh*0.74,900);ctx.restore()});
 const store=state.poster.store||'PESOPLUS';if(store.replace(/\s/g,'').toUpperCase()!=='PESOPLUS'){ctx.fillStyle='#bd0012';ctx.fillRect(224,35,440,112);ctx.fillStyle='#fff';ctx.textAlign='left';everydayText(ctx,store,230,128,430,75,800)}
 const slots=pesoBackState().slots,photos=await Promise.all(slots.map(async slot=>{try{return await loadCanvasImage(slot.image||productFor(slot)?.image||svgThumb('+','#fffdf6'))}catch{return null}}));
 slots.forEach((slot,index)=>{const b=pesoBackCard(index),p=productFor(slot),im=photos[index];
 const discount=Math.round(independentDiscount(slot)*100)/100;
 const nameSize=(b.w<180?19:22)*textScale('name',slot),lineHeight=nameSize*1.08,priceSize=(b.w<180?49:55)*textScale('sale',slot),originalSize=priceSize*.4*textScale('original',slot),extra=p&&discount>0?originalSize*1.15+4:0,photoH=Math.min(b.photo,b.h-priceSize-17-lineHeight*2-extra);
 ctx.save();ctx.beginPath();ctx.rect(b.x,b.y,b.w,b.h);ctx.clip();ctx.fillStyle='#fffdf3';ctx.fillRect(b.x,b.y,b.w,b.h);if(im){const scale=Math.min((b.w-8)/im.width,photoH/im.height);ctx.drawImage(im,b.x+(b.w-im.width*scale)/2,b.y+(photoH-im.height*scale)/2,im.width*scale,im.height*scale)}
 if(p&&discount>0){const badgeR=Math.max(13,Math.min(26,b.w*.15,photoH*.45)),cx=b.x+badgeR+4,cy=b.y+badgeR+4;ctx.save();ctx.fillStyle='#df1830';ctx.beginPath();const bumps=12,steps=bumps*8;for(let i=0;i<=steps;i++){const t=i/steps*Math.PI*2,rr=badgeR*(1+.14*Math.cos(bumps*t)),x=cx+rr*Math.cos(t),y=cy+rr*Math.sin(t);if(i)ctx.lineTo(x,y);else ctx.moveTo(x,y)}ctx.closePath();ctx.fill();ctx.textAlign='center';ctx.fillStyle='#ffdf22';everydayText(ctx,discount+'%',cx,cy-badgeR*.08,badgeR*1.55,badgeR*.78*textScale('discount',slot),800,.9);everydayText(ctx,'OFF',cx,cy+badgeR*.62,badgeR*1.45,badgeR*.52*textScale('discount',slot),800);ctx.restore()}
 ctx.strokeStyle='#dddcd0';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(b.x+b.w-1,b.y+5);ctx.lineTo(b.x+b.w-1,b.y+b.h-3);ctx.stroke();ctx.textAlign='center';ctx.fillStyle='#111';ctx.font=`700 ${nameSize}px Outfit`;let lines=[''];for(const word of (p?.name||'Choose product').split(/\s+/)){const n=lines.length-1,next=(lines[n]+' '+word).trim();if(ctx.measureText(next).width>b.w-14&&lines[n]&&lines.length<2)lines.push(word);else lines[n]=next}lines.forEach((line,i)=>everydayText(ctx,line,b.x+b.w/2,b.y+photoH+nameSize+3+i*lineHeight,b.w-14,nameSize,700,.9));
 if(p){const number=new Intl.NumberFormat('en-PH',{maximumFractionDigits:2}).format(salePrice(p,slot)),symbolSize=priceSize*.56;ctx.font=`800 ${symbolSize}px Arial, sans-serif`;const sw=ctx.measureText('\u20b1').width;ctx.font=`800 ${priceSize}px Outfit`;const nw=Math.min(b.w-sw-16,ctx.measureText(number).width),left=b.x+(b.w-nw-sw-2)/2,saleBaseline=b.y+b.h-8-extra;ctx.textAlign='left';ctx.fillStyle='#ed0015';ctx.font=`800 ${symbolSize}px Arial, sans-serif`;ctx.fillText('\u20b1',left,saleBaseline-5);everydayText(ctx,number,left+sw+2,saleBaseline,nw,priceSize,800);if(discount>0){const originalText='\u20b1'+new Intl.NumberFormat('en-PH',{maximumFractionDigits:2}).format(p.price);ctx.textAlign='center';ctx.fillStyle='#111';const drawnW=everydayText(ctx,originalText,b.x+b.w/2,b.y+b.h-8,b.w-20,originalSize,700);ctx.fillRect(b.x+b.w/2-drawnW/2,b.y+b.h-8-originalSize*.42,drawnW,1.2)}}else{ctx.fillStyle='#ed0015';ctx.textAlign='center';everydayText(ctx,'Add item',b.x+b.w/2,b.y+b.h-8,b.w-14,priceSize,800)}ctx.restore()});return canvas;
}


const PESO_BACK_ART='data:image/jpeg;base64,';
